  addText(head, view.title, 14, C.text, true);
  head.addSpacer();
  addText(head, money(view.cashed) + " cashed", 11, view.cashed > 0 ? C.green : C.dim, true);
  head.addSpacer(6);
  let s = timeStr(data.updated);
  if (data.error || data.ticketsStale) s += " !";
