  addText(w, "🎟️ " + view.title.toUpperCase(), 10, C.dim, true);
  w.addSpacer(4);
  addText(w, money(view.cashed), 26, view.cashed > 0 ? C.green : C.text, true);
  addText(w, "cashed", 10, C.dim, false);
